-- CommandProject: first person (generated by the launcher). Appended to the game's own
-- /lua/ui/game/worldview.lua; CreateMainWorldView calls CPFirstPersonInit. @KEY@ cycles the camera:
--   one unit selected:  strategic -> first person (camera on the unit) -> third person (behind it) -> strategic
--   several selected:   strategic -> command camera (above and behind the formation) -> strategic
-- While a mode is on, W A S D move the unit (or the whole group) relative to where the camera looks,
-- as in an action game (A/D step sideways); the view turns with the mouse while the middle button
-- is held, with Q/E or with the game's own rotation (Space + mouse). F fires at what is under the mouse, X stops, R swaps first/third person and Esc
-- goes back.
-- Everything else stays the game's own: right click orders, abilities, the build menu and its
-- placement work from any camera. With nothing selected @KEY@ keeps its original action.
-- Moves and shots go to the simulation through SimCallback 'CPFirstPerson' (SimSync.lua), which
-- only accepts units of the army that sent them (works the same in multiplayer).
do
local UIUtil = import('/lua/ui/uiutil.lua')
local LayoutHelpers = import('/lua/maui/layouthelpers.lua')
local Bitmap = import('/lua/maui/bitmap.lua').Bitmap

local KEY = '@KEY@'
local SHOW_HUD = @HUD@
local DRIVE_KEYS = @DRIVE@
local FIRST_ZOOM = @FIRST_ZOOM@
local THIRD_ZOOM = @THIRD_ZOOM@
local GROUP_PITCH = 0.75
local THIRD_PITCH = 0.38
local FIRST_PITCH = 0.1

local C_PANEL = 'C80E161E'
local C_TEXT = 'FFE6EEF5'
local C_FAINT = 'FF9AA6B2'
local C_ACCENT = 'FFF2B33D'
local C_GOOD = 'FF63E08E'
local C_BAD = 'FFFF6060'

local Mode = 'off'
local Units = {}
local Saved = false
local Loop = false
local Hud = false
local Overridden = false
local Pressed = {}
local Driving = false
local Ready = false

local function Notify(text, color)
    pcall(function()
        import('/lua/ui/game/textdisplay.lua').PrintToScreen({
            text = text, size = 16, color = color or C_ACCENT, duration = 4, location = 'centertop',
        })
    end)
end

local function Px(n)
    return n * LayoutHelpers.GetPixelScaleFactor()
end

local function Cam()
    return GetCamera('WorldCamera')
end

local function Now()
    local t = 0
    pcall(function() t = CurrentTime() end)
    return t
end

local function Alive(list)
    local out = {}
    for _, u in list or {} do
        local ok, dead = pcall(function() return u:IsDead() end)
        if ok and not dead then table.insert(out, u) end
    end
    return out
end

local function Pos(u)
    local ok, p = pcall(function() return u:GetPosition() end)
    if ok and p then return p end
    return nil
end

local function Center(list)
    local x, y, z, n = 0, 0, 0, 0
    for _, u in list do
        local p = Pos(u)
        if p then
            x = x + p[1]; y = y + p[2]; z = z + p[3]; n = n + 1
        end
    end
    if n == 0 then return nil end
    return { x / n, y / n, z / n }
end

local function Spread(list, c)
    local r = 0
    for _, u in list do
        local p = Pos(u)
        if p then
            local d = math.sqrt((p[1] - c[1]) * (p[1] - c[1]) + (p[3] - c[3]) * (p[3] - c[3]))
            if d > r then r = d end
        end
    end
    return r
end

local function Name(u)
    local name = '?'
    pcall(function()
        local bp = u:GetBlueprint()
        name = (bp.General and bp.General.UnitName) or bp.Description or bp.BlueprintId or name
        if type(name) == 'string' and string.sub(name, 1, 5) == '<LOC ' then
            name = LOC(name)
        end
    end)
    return tostring(name)
end

local function Health(u)
    local h, m = 0, 1
    pcall(function() h = u:GetHealth(); m = u:GetMaxHealth() end)
    if not m or m <= 0 then return 1 end
    return math.max(0, math.min(1, h / m))
end

-- held keys: a hold only starts with a real key press (the key map calls CPFirstPersonKey), so a
-- key the engine still thinks is down from before never moves the unit by itself. It goes on while
-- the engine's IsKeyDown says the key is down (asked by name or by its code, once it has answered
-- for that key); without IsKeyDown, while Windows keeps repeating the key (the first press counts
-- for a while: Windows waits before repeating a held key)
local KeyCode = {}
local Holding = {}
local function KeyDown(key)
    local tries = { key }
    if string.len(key) == 1 then table.insert(tries, string.byte(key)) end
    if KeyCode[key] ~= nil then tries = { KeyCode[key] } end
    local answered = false
    for _, k in tries do
        local ok, down = pcall(IsKeyDown, k)
        if ok and down == true then
            KeyCode[key] = k
            return true
        end
        if ok and down == false then answered = true end
    end
    if KeyCode[key] ~= nil and answered then return false end
    return nil
end

local function Held(key)
    if not Holding[key] then return false end
    local down = KeyDown(key)
    if down == nil then
        local p = Pressed[key]
        down = p and (Now() - p.last) < (p.n >= 2 and 0.3 or 0.7)
    end
    if not down then Holding[key] = false end
    return down and true or false
end

local function Send(args, withSelection)
    pcall(function() SimCallback({ Func = 'CPFirstPerson', Args = args }, withSelection ~= false) end)
end

-- ------------------------------------------------------------------ keys while a mode is on

local function Action(fn)
    return { action = 'UI_Lua import("/lua/ui/game/worldview.lua").' .. fn, category = 'ui', order = 98 }
end

-- the keys the mod takes while a mode is on (Shift + W A S D too: the game zooms with Shift-W)
local OVERRIDE = { 'W', 'A', 'S', 'D', 'Q', 'E', 'F', 'X', 'R', 'Esc', 'Shift-W', 'Shift-A', 'Shift-S', 'Shift-D', 'Shift-Q', 'Shift-E' }

local function BaseKey(k)
    if string.sub(k, 1, 6) == 'Shift-' then return string.sub(k, 7) end
    return k
end

local function OriginalFor(key)
    local act = nil
    pcall(function()
        local km = import('/lua/keymap/keymapper.lua')
        local name = km.GetCurrentKeyMap()[key]
        if name then act = km.GetKeyActions()[name] end
    end)
    return act
end

local function BindDrive()
    if Overridden or not DRIVE_KEYS then return end
    local t = {}
    for _, k in OVERRIDE do
        t[k] = Action('CPFirstPersonKey("' .. BaseKey(k) .. '")')
    end
    -- out first, then in: the game's own action for the key (zoom, attack, stop...) must not run too
    pcall(IN_RemoveKeyMapTable, t)
    pcall(IN_AddKeyMapTable, t)
    Overridden = true
end

local function UnbindDrive()
    if not Overridden then return end
    Overridden = false
    local back, gone = {}, {}
    for _, k in OVERRIDE do
        local a = OriginalFor(k)
        if a then back[k] = a else gone[k] = Action('CPFirstPersonKey("' .. BaseKey(k) .. '")') end
    end
    pcall(IN_RemoveKeyMapTable, gone)
    pcall(IN_AddKeyMapTable, back)
end

local function BindToggle()
    pcall(IN_AddKeyMapTable, { [KEY] = Action('CPFirstPersonToggle()') })
end

-- ------------------------------------------------------------------ interface

local function Text(parent, text, size, color)
    local t = UIUtil.CreateText(parent, text, size, UIUtil.bodyFont)
    t:SetColor(color or C_TEXT)
    t:DisableHitTest()
    return t
end

local function Rect(parent, color, w, h)
    local b = Bitmap(parent)
    b:SetSolidColor(color)
    b.Width:Set(Px(w))
    b.Height:Set(Px(h))
    b:DisableHitTest()
    return b
end

local function BuildHud()
    if Hud or not SHOW_HUD then return end
    local frame = GetFrame(0)
    Hud = {}
    -- crosshair (first person)
    Hud.cross = Bitmap(frame)
    Hud.cross:DisableHitTest()
    Hud.cross.Width:Set(Px(26))
    Hud.cross.Height:Set(Px(26))
    LayoutHelpers.AtCenterIn(Hud.cross, frame)
    local h = Rect(Hud.cross, 'D0FFFFFF', 26, 2)
    LayoutHelpers.AtCenterIn(h, Hud.cross)
    local v = Rect(Hud.cross, 'D0FFFFFF', 2, 26)
    LayoutHelpers.AtCenterIn(v, Hud.cross)
    local dot = Rect(Hud.cross, 'FFF2B33D', 4, 4)
    LayoutHelpers.AtCenterIn(dot, Hud.cross)
    -- info panel (top center)
    Hud.panel = Rect(frame, C_PANEL, 560, 58)
    LayoutHelpers.AtHorizontalCenterIn(Hud.panel, frame)
    LayoutHelpers.AtTopIn(Hud.panel, frame, 70)
    local bar = Rect(Hud.panel, C_ACCENT, 4, 58)
    LayoutHelpers.AtLeftTopIn(bar, Hud.panel, 0, 0)
    Hud.mode = Text(Hud.panel, '', 12, C_ACCENT)
    LayoutHelpers.AtLeftTopIn(Hud.mode, Hud.panel, 14, 6)
    Hud.name = Text(Hud.panel, '', 15, C_TEXT)
    LayoutHelpers.AtLeftTopIn(Hud.name, Hud.panel, 14, 22)
    Hud.lifeBack = Rect(Hud.panel, 'FF23384B', 150, 6)
    LayoutHelpers.AtRightTopIn(Hud.lifeBack, Hud.panel, 14, 12)
    Hud.life = Rect(Hud.lifeBack, C_GOOD, 150, 6)
    LayoutHelpers.AtLeftTopIn(Hud.life, Hud.lifeBack, 0, 0)
    Hud.lifeText = Text(Hud.panel, '', 11, C_FAINT)
    LayoutHelpers.AtRightTopIn(Hud.lifeText, Hud.panel, 14, 22)
    Hud.keys = Text(Hud.panel, '', 11, C_FAINT)
    LayoutHelpers.AtLeftTopIn(Hud.keys, Hud.panel, 14, 40)
end

local MODE_LABEL = {
    first = 'PRIMEIRA PESSOA',
    third = 'TERCEIRA PESSOA',
    group = 'CAMERA DE COMANDO',
}

local function UpdateHud()
    if not SHOW_HUD then return end
    if not Hud then
        if not pcall(BuildHud) then Hud = false; return end
    end
    if Mode == 'off' then
        Hud.cross:Hide()
        Hud.panel:Hide()
        return
    end
    Hud.panel:Show()
    if Mode == 'first' then Hud.cross:Show() else Hud.cross:Hide() end
    local n = table.getn(Units)
    Hud.mode:SetText(MODE_LABEL[Mode] .. '   ' .. KEY .. ' troca a camera')
    if n == 1 then
        Hud.name:SetText(Name(Units[1]))
    else
        Hud.name:SetText(n .. ' unidades')
    end
    local life = 0
    for _, u in Units do life = life + Health(u) end
    life = n > 0 and life / n or 0
    Hud.life.Width:Set(Px(150 * life))
    Hud.life:SetSolidColor(life > 0.5 and C_GOOD or (life > 0.25 and C_ACCENT or C_BAD))
    Hud.lifeText:SetText(math.floor(life * 100 + 0.5) .. '% vida')
    if DRIVE_KEYS then
        Hud.keys:SetText('W A S D andar   botao do meio + mouse ou Q/E olhar   F atirar   X parar' .. (n == 1 and '   R 1a/3a' or '') .. '   Esc sair')
    else
        Hud.keys:SetText('Botao direito: ordens   Esc sair')
    end
end

-- ------------------------------------------------------------------ cameras

-- The game's camera is an orbit camera: a focus point, a heading, a pitch and a zoom. The mod owns
-- the heading while a mode is on (A/D turn it, or it follows where the unit walks).
-- First person switches the camera to absolute coordinates, as the game's own cinematics do: the
-- zoom is then a real distance with no minimum, so a short zoom puts the eye right behind the
-- focus, and the focus goes just ahead of the unit's head. Third person and the command camera use
-- the normal camera. Positions are smoothed, so the unit's steps don't shake the view.
-- (Camera:NoseCam is not used: it is unfinished in the engine and closes the game.)
local DIRS = {
    function(h) return -math.sin(h), -math.cos(h) end,
    function(h) return math.sin(h), -math.cos(h) end,
    function(h) return -math.sin(h), math.cos(h) end,
    function(h) return math.sin(h), math.cos(h) end,
}
-- heading pi looks to the top of the map (CameraDefaults.InitialHeading) and grows turning left
-- (seen in the game): formula 3 when it can't be measured
local Calib = 3
local CalibNote = ''
local Calibrated = false
-- h: heading the mod keeps; eye/focus: smoothed points; anchor: last place the unit was seen
-- (to know where it walks); want: heading of that walk; key: ids of the units
local View = { h = false, eye = false, focus = false, anchor = false, want = false, key = '' }
local TURN_RATE = 1.5
-- first person: distance from the eye to the focus (absolute coordinates)
local FP_DIST = 0.6
-- mouse look: radians per pixel
local MOUSE_TURN = 0.006
local Absolute = false

local function DirOf(h)
    return DIRS[Calib](h)
end

local atan2 = math.atan2 or function(y, x) return math.atan(y, x) end

local function HeadingOf(dx, dz)
    if Calib == 1 then return atan2(-dx, -dz)
    elseif Calib == 2 then return atan2(dx, -dz)
    elseif Calib == 3 then return atan2(-dx, dz) end
    return atan2(dx, dz)
end

local function Finite(v)
    return type(v) == 'number' and v == v and v > -1e9 and v < 1e9
end

local function LerpAngle(a, b, t)
    local d = b - a
    while d > math.pi do d = d - 2 * math.pi end
    while d < -math.pi do d = d + 2 * math.pi end
    return a + d * t
end

-- turns a heading to the right (positive) or left (negative) by an angle, whatever way the
-- engine counts headings: x grows to the right of the map, z towards the bottom
local function Turn(h, a)
    local dx, dz = DirOf(h)
    local rx, rz = -dz, dx
    local c, s = math.cos(a), math.sin(a)
    return HeadingOf(dx * c + rx * s, dz * c + rz * s)
end

local function Smooth(cur, target, rate, dt)
    if not cur then return { target[1], target[2], target[3] } end
    local k = 1 - math.exp(-rate * dt)
    return { cur[1] + (target[1] - cur[1]) * k, cur[2] + (target[2] - cur[2]) * k, cur[3] + (target[3] - cur[3]) * k }
end

local function MinZoom(cam)
    local z = FIRST_ZOOM
    pcall(function() z = cam:GetMinZoom() or z end)
    if not Finite(z) or z <= 0 then z = 5 end
    return z
end

local function Snap(cam, focus, h, pitch, zoom, free)
    if not (Finite(focus[1]) and Finite(focus[2]) and Finite(focus[3]) and Finite(h) and Finite(pitch) and Finite(zoom)) then return false end
    if not free then zoom = math.max(MinZoom(cam), zoom) end
    local ok = pcall(function() cam:SnapTo(focus, { h, pitch, 0 }, zoom) end)
    return ok
end

local function SetAbsolute(cam, on)
    if Absolute == on then return end
    Absolute = on
    pcall(function() cam:UseAbsoluteCoords(on) end)
end

-- which way the heading turns the view, measured once on the strategic camera: for the right
-- formula a point ahead of the focus shows up higher on the screen and a point to its right, to
-- the right
local function ScreenOf(p)
    local v = viewLeft:Project(Vector(p[1], p[2], p[3]))
    local x, y = v.x or v[1], v.y or v[2]
    if not (Finite(x) and Finite(y)) then error('sem projeção') end
    return x, y
end

local function Calibrate(cam)
    if Calibrated then return end
    Calibrated = true
    local found = false
    local ok, err = pcall(function()
        local s = cam:SaveSettings()
        local f, h = s.Focus, s.Heading or 0
        local cx, cy = ScreenOf(f)
        for k, dir in DIRS do
            local dx, dz = dir(h)
            local _, ay = ScreenOf({ f[1] + dx * 20, f[2], f[3] + dz * 20 })
            local rx = ScreenOf({ f[1] - dz * 20, f[2], f[3] + dx * 20 })
            if ay < cy - 1 and rx > cx + 1 then
                Calib = k
                found = true
                return
            end
        end
    end)
    CalibNote = tostring(found) .. ' ' .. tostring(ok and '' or err)
    LOG('*CPFP: camera calibrada (' .. tostring(Calib) .. ', ' .. CalibNote .. ')')
end

-- size of the unit's model: width, height, length (the mesh extents of the blueprint, or its size)
local DimCache = {}
local function Dims(u)
    local id = 'x'
    pcall(function() id = u:GetEntityId() end)
    if DimCache[id] then return DimCache[id][1], DimCache[id][2], DimCache[id][3] end
    local w, h, d = 1, 1, 1
    pcall(function()
        local bp = u:GetBlueprint()
        local ph = bp.Physics or {}
        -- the game fills the extents it doesn't have with 0
        local function pick(a, b, def)
            a, b = tonumber(a), tonumber(b)
            if a and a > 0 then return a end
            if b and b > 0 then return b end
            return def
        end
        w = pick(ph.MeshExtentsX, bp.SizeX, w)
        h = pick(ph.MeshExtentsY, bp.SizeY, h)
        d = pick(ph.MeshExtentsZ, bp.SizeZ, d)
    end)
    local function clamp(v) if not Finite(v) then return 1 end return math.max(0.3, math.min(40, v)) end
    w, h, d = clamp(w), clamp(h), clamp(d)
    DimCache[id] = { w, h, d }
    LOG('*CPFP: tamanho da unidade ' .. tostring(id) .. ': ' .. w .. ' x ' .. h .. ' x ' .. d)
    return w, h, d
end

-- the player turned the view with the game's own controls (Space + mouse): the camera reports a
-- heading (and pitch) other than the one the mod set last frame, so the view keeps that turn
local function AdoptTurn(cam)
    local ok, s = pcall(function() return cam:SaveSettings() end)
    if not ok or not s then return end
    if View.setH and Finite(s.Heading) then
        local d = LerpAngle(0, s.Heading - View.setH, 1)
        if math.abs(d) > 0.002 and math.abs(d) < 1.5 then
            View.h = View.h + d
            View.want = false
        end
    end
    if View.setP and Finite(s.Pitch) then
        local d = s.Pitch - View.setP
        if math.abs(d) > 0.002 and math.abs(d) < 1 then View.pitch = math.max(-0.45, math.min(0.9, (View.pitch or FIRST_PITCH) + d)) end
    end
end

-- the mod's heading: Q/E (and the game's rotation) turn it; when the unit walks by orders and no
-- key moves it, the view follows where it goes
local function SteerHeading(p, turn, dt, follow)
    if turn ~= 0 then
        View.h = Turn(View.h, turn * TURN_RATE * dt)
        View.want = false
    end
    if not p then return end
    if not View.anchor then
        View.anchor = { p[1], p[3] }
        return
    end
    local dx, dz = p[1] - View.anchor[1], p[3] - View.anchor[2]
    local d = math.sqrt(dx * dx + dz * dz)
    if d > 0.35 then
        View.anchor = { p[1], p[3] }
        View.movedAt = Now()
        -- where the unit faces: units turn to where they walk
        View.face = HeadingOf(dx / d, dz / d)
        if follow and turn == 0 then
            View.want = HeadingOf(dx / d, dz / d)
        end
    end
    -- only while it is walking: once it stops, the view stays where the player left it
    if follow and turn == 0 and View.want and View.movedAt and Now() - View.movedAt < 0.6 then
        View.h = LerpAngle(View.h, View.want, 1 - math.exp(-2.5 * dt))
    end
end

local function FollowFirst(cam, dt, turn, driving)
    local u = Units[1]
    local p = Pos(u)
    if not p then return end
    -- driving: the view is the player's (Q/E, Space + mouse); walking by orders: it follows the unit
    AdoptTurn(cam)
    SteerHeading(p, turn, dt, not driving)
    local h = View.h
    local fx, fz = DirOf(h)
    local w, ht, len = Dims(u)
    -- the eye: in front of the unit's face (the way it faces, not the way the view looks, so its
    -- own body stays out of the picture), a little above the top of the model
    View.faceS = LerpAngle(View.faceS or View.face or h, View.face or h, 1 - math.exp(-5 * dt))
    local ox, oz = DirOf(View.faceS)
    local up = ht + 0.3
    local ahead = math.max(len, w) * 0.55 + 0.25
    View.eye = Smooth(View.eye, { p[1] + ox * ahead, p[2] + up, p[3] + oz * ahead }, 14, dt)
    local eye = View.eye
    local pitch = View.pitch or FIRST_PITCH
    local c = FP_DIST * math.cos(pitch)
    local focus = { eye[1] + fx * c, eye[2] - FP_DIST * math.sin(pitch), eye[3] + fz * c }
    SetAbsolute(cam, true)
    if Snap(cam, focus, h, pitch, FP_DIST, true) then
        View.setH = h
        View.setP = pitch
    end
end

local function Follow(dt, turn, driving)
    local cam = Cam()
    if Mode == 'first' then
        FollowFirst(cam, dt, turn, driving)
        return
    end
    SetAbsolute(cam, false)
    local c = Center(Units)
    if not c then return end
    local s = cam:SaveSettings()
    AdoptTurn(cam)
    View.setP = nil
    if DRIVE_KEYS then
        SteerHeading(table.getn(Units) == 1 and c or nil, turn, dt, Mode == 'third' and not driving)
    end
    local zoom = s.Zoom
    local pitch = THIRD_PITCH
    local lift = 2
    if Mode == 'group' then
        pitch = GROUP_PITCH
        local want = math.max(60, Spread(Units, c) * 2.4 + 40)
        if not Finite(zoom) or zoom < want * 0.5 then zoom = want end
    else
        local _, ht = Dims(Units[1])
        lift = ht * 0.7
        if not Finite(zoom) or zoom < MinZoom(cam) then zoom = THIRD_ZOOM end
    end
    View.focus = Smooth(View.focus, { c[1], c[2] + lift, c[3] }, 10, dt)
    if Snap(cam, View.focus, View.h, pitch, zoom) then View.setH = View.h end
end

local function Exit(quiet)
    if Mode == 'off' then return end
    if Driving then
        Send({ Cmd = 'halt' })
        Driving = false
    end
    Mode = 'off'
    Holding = {}
    UnbindDrive()
    pcall(UpdateHud)
    local cam = Cam()
    SetAbsolute(cam, false)
    if Saved then
        local s = Saved
        local function restore()
            pcall(function() cam:RestoreSettings(s) end)
            pcall(function() cam:MoveTo(s.Focus, { s.Heading, s.Pitch, 0 }, s.Zoom, 0) end)
        end
        restore()
        -- the engine takes a frame to leave absolute coordinates: put the view back again after it
        ForkThread(function()
            WaitFrames(2)
            if Mode == 'off' then restore() end
        end)
    else
        pcall(function() cam:Reset() end)
    end
    Saved = false
    LOG('*CPFP: camera estrategica')
    if not quiet then Notify('Camera estrategica') end
end

local function IdsOf(list)
    local ids = {}
    for _, u in list do
        local id = '?'
        pcall(function() id = tostring(u:GetEntityId()) end)
        table.insert(ids, id)
    end
    return table.concat(ids, ',')
end

local function Start(mode, units)
    local cam = Cam()
    local s = false
    pcall(function() s = cam:SaveSettings() end)
    if Mode == 'off' then
        Saved = s
        -- measured on the strategic camera, before the mod moves it
        Calibrate(cam)
    end
    local key = IdsOf(units)
    -- same units: keep the view; new units: start looking where the camera looked
    if key ~= View.key or not View.h then
        View = { h = (s and s.Heading) or 0, eye = false, focus = false, anchor = false, want = false, key = key }
    else
        View.eye = false
        View.focus = false
        View.setH = nil
        View.setP = nil
    end
    Units = units
    pcall(SelectUnits, units)
    LOG('*CPFP: modo ' .. mode .. ' com ' .. table.getn(units) .. ' unidade(s)')
    SetAbsolute(cam, mode == 'first')
    if mode == 'third' and s then
        local _, ht = Dims(units[1])
        local c = Center(units)
        if c then Snap(cam, { c[1], c[2] + ht * 0.7, c[3] }, View.h, THIRD_PITCH, THIRD_ZOOM) end
    elseif mode == 'group' and s then
        local c = Center(units)
        if c then Snap(cam, { c[1], c[2] + 2, c[3] }, View.h, GROUP_PITCH, math.max(60, Spread(units, c) * 2.4 + 40)) end
    end
    Mode = mode
    BindDrive()
    pcall(UpdateHud)
end

local function Selected()
    local sel = {}
    pcall(function() sel = GetSelectedUnits() or {} end)
    return Alive(sel)
end

-- the drive keys as numbers: forward (W +1, S -1), sideways (D +1 right, A -1 left) and turn
-- (E +1 right, Q -1 left)
local function DriveInput()
    if not DRIVE_KEYS then return 0, 0, 0 end
    local f, side, t = 0, 0, 0
    if Held('W') then f = f + 1 end
    if Held('S') then f = f - 1 end
    if Held('D') then side = side + 1 end
    if Held('A') then side = side - 1 end
    if Held('E') then t = t + 1 end
    if Held('Q') then t = t - 1 end
    return f, side, t
end

-- mouse look: with the middle mouse button held, moving the mouse turns the view (and in first
-- person tilts it up and down), as in an action game
local MouseLast = false
local function MouseLook()
    local held = false
    pcall(function() held = IsKeyDown('MBUTTON') == true end)
    if not held or not View.h then
        MouseLast = false
        return
    end
    local x, y = false, false
    pcall(function()
        local m = GetMouseScreenPos()
        x, y = m.x or m[1], m.y or m[2]
    end)
    if not (Finite(x) and Finite(y)) then return end
    if MouseLast then
        local dx, dy = x - MouseLast[1], y - MouseLast[2]
        if dx ~= 0 then
            View.h = Turn(View.h, dx * MOUSE_TURN)
            View.want = false
        end
        if dy ~= 0 and Mode == 'first' then
            View.pitch = math.max(-0.45, math.min(0.9, (View.pitch or FIRST_PITCH) + dy * MOUSE_TURN * 0.8))
        end
    end
    MouseLast = { x, y }
end

local function Tick()
    local last = Now()
    local lastHud = 0
    -- what was last sent to the units: forward, direction and when
    local sent = { f = 0, s = 0, dx = 0, dz = 0, t = -10 }
    while Mode ~= 'off' do
        local t = Now()
        local dt = t - last
        if not Finite(dt) or dt <= 0 or dt > 0.25 then dt = 1 / 60 end
        last = t
        Units = Alive(Units)
        -- the player picked other units: the camera goes with them (compared by id: the game
        -- hands out a new object for the same unit on every call)
        local sel = Selected()
        if table.getn(sel) > 0 and IdsOf(sel) ~= View.key then
            local mode = Mode
            if table.getn(sel) > 1 then mode = 'group' elseif mode == 'group' then mode = 'third' end
            Start(mode, sel)
        end
        if table.getn(Units) == 0 then
            Notify('Unidade destruida', C_BAD)
            Exit(true)
            break
        end
        local f, side, turn = DriveInput()
        MouseLook()
        local moving = f ~= 0 or side ~= 0
        local okF, errF = pcall(Follow, dt, turn, moving)
        if not okF then LOG('*CPFP: camera: ' .. tostring(errF)) end
        if DRIVE_KEYS then
            if moving then
                local dx, dz = DirOf(View.h or 0)
                local turned = (dx - sent.dx) * (dx - sent.dx) + (dz - sent.dz) * (dz - sent.dz) > 0.012
                -- a new order only when needed: each one makes the unit plan its path again
                if f ~= sent.f or side ~= sent.s or (turned and t - sent.t >= 0.2) or t - sent.t >= 0.9 then
                    Send({ Cmd = 'drive', F = f, S = side, DX = dx, DZ = dz })
                    sent = { f = f, s = side, dx = dx, dz = dz, t = t }
                    Driving = true
                end
            elseif Driving then
                Send({ Cmd = 'halt' })
                sent = { f = 0, s = 0, dx = 0, dz = 0, t = t }
                Driving = false
            end
        end
        if t - lastHud > 0.2 then
            lastHud = t
            pcall(UpdateHud)
        end
        WaitFrames(1)
    end
    Loop = false
end

-- ------------------------------------------------------------------ entry points (key map)

function CPFirstPersonKey(key)
    if Mode == 'off' then return end
    local t = Now()
    local p = Pressed[key]
    if p and t - p.last < 0.7 then
        p.last = t
        p.n = p.n + 1
    else
        Pressed[key] = { last = t, n = 1 }
    end
    Holding[key] = true
    if key == 'Esc' then
        Exit()
    elseif key == 'X' then
        Send({ Cmd = 'stop' })
        Driving = false
    elseif key == 'R' then
        if table.getn(Units) == 1 then
            if Mode == 'first' then Start('third', Units) else Start('first', Units) end
        end
    elseif key == 'F' then
        local info = false
        pcall(function() info = GetRolloverInfo() end)
        local id = false
        if info and info.userUnit and info.armyIndex and info.armyIndex ~= GetFocusArmy() then
            pcall(function() id = info.userUnit:GetEntityId() end)
        end
        if id then
            Send({ Cmd = 'fire', Target = id })
        else
            local p = false
            pcall(function() p = GetMouseWorldPos() end)
            if p then Send({ Cmd = 'fire', Pos = { p[1], p[2], p[3] } }) end
        end
    end
end

function CPFirstPersonToggle()
    if not Ready then return end
    if Mode == 'off' then
        local sel = Selected()
        local n = table.getn(sel)
        if n == 0 then
            -- nothing selected: the key keeps its original job
            local a = OriginalFor(KEY)
            if a and a.action then pcall(ConExecute, a.action) end
            return
        end
        Start(n == 1 and 'first' or 'group', sel)
        if not Loop then
            Loop = ForkThread(Tick)
        end
    elseif Mode == 'first' then
        Start('third', Units)
    else
        Exit()
    end
end

function CPFirstPersonInit()
    if Ready then return end
    local replay = false
    pcall(function() replay = SessionIsReplay() end)
    if replay or GetFocusArmy() == -1 then return end
    Ready = true
    BindToggle()
    -- the game may rebuild the key map after the interface is ready: bind again a little later
    ForkThread(function()
        WaitSeconds(3)
        BindToggle()
        WaitSeconds(10)
        BindToggle()
    end)
    Notify('CommandProject: selecione unidades e aperte ' .. KEY .. ' para a camera em primeira pessoa')
end
end
